script:
// Welle A06 – Desk-Knopf „Angerufen“: setzt die Erstreaktion (erstreaktion_am, reaktionszeit_min)
// und den Status „Neu“ -> „Kontaktversuch“ über oekovolt_app.website_api.sla.angerufen.
frappe.ui.form.on('Kontaktanfrage', {
	refresh(frm) {
		if (frm.is_new() || frm.doc.erstreaktion_am || !frm.perm[0] || !frm.perm[0].write) return;
		frm.add_custom_button(__('Angerufen'), () => {
			frappe.call({
				method: 'oekovolt_app.website_api.sla.angerufen',
				args: { doctype: frm.doctype, name: frm.doc.name },
				freeze: true,
				freeze_message: __('Erstreaktion wird gespeichert …'),
				callback: () => {
					frappe.show_alert({ message: __('Erstreaktion gespeichert'), indicator: 'green' });
					frm.reload_doc();
				},
			});
		}).addClass('btn-primary');
	},
});

